export const key='mtelk.field-guide.v1';
const pathPattern=/^\/(?:education(?:\/(?:lessons\/[a-z0-9-]+|deer-calling))?|calls\/[a-z0-9-]+|archive(?:\/[a-z0-9-]+)?|legacy|support|videos(?:\/watch\/[A-Za-z0-9_-]{11})?|banding|about|canada(?:\/education|\/presentation)?)\/$/;
export const eligible=url=>typeof url==='string'&&pathPattern.test(url);
function clean(items){return [...new Map(items.filter(r=>r&&eligible(r.url)&&typeof r.title==='string'&&typeof r.description==='string').map(r=>[r.url,{url:r.url,title:r.title.slice(0,180),description:r.description.slice(0,500)}])).values()].slice(0,50)}
export function readSaved(){try{const raw=localStorage.getItem(key);if(!raw)return {items:[],issue:''};const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error('Invalid saved guide');return {items:clean(parsed),issue:''}}catch{return {items:[],issue:'Your saved guide could not be read. Browser storage may be unavailable or its saved data may need clearing.'}}}
function write(items){const raw=JSON.stringify(clean(items));localStorage.setItem(key,raw);if(localStorage.getItem(key)!==raw)throw Error('Saving unavailable');window.dispatchEvent(new Event('field-guide-change'))}
export function toggleSaved(record){const state=readSaved();if(state.issue)throw Error(state.issue);if(!eligible(record.url))throw Error('This resource cannot be saved.');const exists=state.items.some(r=>r.url===record.url);if(!exists&&state.items.length>=50)throw Error('Your guide has 50 resources. Remove one before saving another.');write(exists?state.items.filter(r=>r.url!==record.url):[record,...state.items]);return !exists}
export function removeSaved(url){const state=readSaved();if(state.issue)throw Error(state.issue);write(state.items.filter(r=>r.url!==url))}
export function clearSaved(){localStorage.removeItem(key);if(localStorage.getItem(key)!==null)throw Error('Clearing unavailable');window.dispatchEvent(new Event('field-guide-change'))}
export function makeSaveButton(record){const button=document.createElement('button');button.type='button';button.className='resource-save';const status=document.createElement('span');status.className='resource-save-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');function refresh(){const saved=readSaved().items.some(r=>r.url===record.url);button.textContent=saved?'Remove from Field Guide':'Save to Field Guide';button.setAttribute('aria-pressed',String(saved))}button.onclick=()=>{try{const saved=toggleSaved(record);status.textContent=saved?'Saved on this browser.':'Removed from your guide.';refresh()}catch(error){status.textContent=error.message}};window.addEventListener('field-guide-change',refresh);window.addEventListener('storage',refresh);refresh();return {button,status}}
